rootStyle.customCss:
.pg-root{font-family:var(--font-figtree),Figtree,Arial,sans-serif}
.dy-wave{height:auto;aspect-ratio:5/2}
.dy-hero-img,.dy-wave{pointer-events:none}
@media (min-width:1024px){.dy-hero{height:calc(100vh - 150px);max-height:1000px}.dy-hero>.pg-inner{height:100%}.dy-hero-img{height:calc((100% + 55px) * 1.1);width:auto;aspect-ratio:2/3}.dy-wave{top:50%}}
.dy-quote strong{color:#fff;font-weight:700}
.dy-zoom img{transition:transform .7s ease-out}
.dy-card:hover .dy-zoom img{transform:scale(1.05)}
.dy-arrow,.dy-chevron{transition:transform .3s}
.dy-card:hover .dy-arrow,.dy-btn:hover .dy-arrow{transform:translateX(4px)}
.dy-nav-item:hover .dy-chevron,.dy-nav-item:focus-within .dy-chevron{transform:rotate(180deg)}
.dy-dd{visibility:hidden;pointer-events:none;translate:0 12px;transition:opacity .3s ease-out,translate .3s ease-out,visibility .3s}
.dy-nav-item:hover>.dy-dd,.dy-nav-item:focus-within>.dy-dd{visibility:visible;pointer-events:auto;translate:0 0;opacity:1}

publishedRootStyle.customCss:
.pg-root{font-family:var(--font-figtree),Figtree,Arial,sans-serif}
.dy-hero{border-radius:0 0 0 160px}
.dy-wave{height:auto;aspect-ratio:5/2}
.dy-hero-img,.dy-wave{pointer-events:none}
@media (min-width:1024px){.dy-hero{height:calc(100vh - 150px);max-height:1000px}.dy-hero>.pg-inner{height:100%}.dy-hero-img{height:calc((100% + 55px) * 1.1);width:auto;aspect-ratio:2/3}.dy-wave{top:50%}}
@media (max-width:1023px){.dy-hero{border-radius:0 0 0 96px}}
@media (max-width:639px){.dy-hero{border-radius:0 0 0 40px}}
.dy-italic{font-style:italic}
.dy-quote strong{color:#fff;font-weight:700}
.dy-top img{object-position:top}
.dy-clamp>span{display:-webkit-box!important;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
.dy-zoom img{transition:transform .7s ease-out}
.dy-card:hover .dy-zoom img{transform:scale(1.05)}
.dy-arrow,.dy-chevron{transition:transform .3s}
.dy-card:hover .dy-arrow,.dy-btn:hover .dy-arrow{transform:translateX(4px)}
.dy-nav-item:hover .dy-chevron,.dy-nav-item:focus-within .dy-chevron{transform:rotate(180deg)}
.dy-dd{visibility:hidden;pointer-events:none;translate:0 12px;transition:opacity .3s ease-out,translate .3s ease-out,visibility .3s}
.dy-nav-item:hover>.dy-dd,.dy-nav-item:focus-within>.dy-dd{visibility:visible;pointer-events:auto;translate:0 0;opacity:1}
.dy-sticky{translate:0 -110%;transition:translate .3s ease-in-out}
.dy-sticky.is-on{translate:0 0}
